import React, { useState } from 'react';
import { DocumentIcon } from '@heroicons/react/24/solid';

const DocumentUploadPage: React.FC = () => {
  const [pdfFile, setPdfFile] = useState<File | null>(null);
  const [extractedText, setExtractedText] = useState<string>('');
  const [isLoading, setIsLoading] = useState(false);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      if (file.type === 'application/pdf') {
        setPdfFile(file);
        setExtractedText('');
      } else {
        alert('Please upload a PDF file');
      }
    }
  };

  const handleGenerateSpeech = async () => {
    if (!extractedText) {
      alert('Please upload a document and extract text first');
      return;
    }
    
    setIsLoading(true);
    try {
      // Here we'll add the API call to generate speech
      console.log('Generating speech for:', extractedText);
      // For now, we'll just show a success message
      alert('Speech generation started! (API integration pending)');
    } catch (error) {
      console.error('Error generating speech:', error);
      alert('Error generating speech. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleExtractText = async () => {
    if (!pdfFile) {
      alert('Please upload a PDF file first');
      return;
    }

    setIsLoading(true);
    try {
      // Here we'll add the API call to extract text
      // For now, we'll just set some dummy text
      setExtractedText('Sample extracted text from the PDF document. This will be replaced with actual extracted text from the backend API.');
    } catch (error) {
      console.error('Error extracting text:', error);
      alert('Error extracting text from PDF. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="max-w-4xl mx-auto p-6">
      <h1 className="text-3xl font-bold text-center mb-8">Document Upload</h1>
      
      <div className="space-y-8">
        <div className="bg-white p-6 rounded-lg shadow-md">
          <h2 className="text-xl font-semibold mb-4">Upload PDF Document</h2>
          <div className="flex flex-col items-center">
            <input
              type="file"
              accept=".pdf"
              onChange={handleFileUpload}
              className="block w-full text-sm text-gray-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-50 file:text-blue-700 hover:file:bg-blue-100"
            />
            {pdfFile && (
              <div className="mt-4 flex items-center text-gray-600">
                <DocumentIcon className="h-5 w-5 mr-2" />
                <span>{pdfFile.name}</span>
              </div>
            )}
          </div>
          {pdfFile && (
            <button
              onClick={handleExtractText}
              disabled={isLoading}
              className="mt-4 w-full px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors disabled:bg-blue-300"
            >
              {isLoading ? 'Extracting Text...' : 'Extract Text'}
            </button>
          )}
        </div>

        {extractedText && (
          <div className="bg-white p-6 rounded-lg shadow-md">
            <h2 className="text-xl font-semibold mb-4">Extracted Text</h2>
            <div className="bg-gray-50 p-4 rounded-lg mb-4 max-h-60 overflow-y-auto">
              <p className="text-gray-700 whitespace-pre-wrap">{extractedText}</p>
            </div>
            <button
              onClick={handleGenerateSpeech}
              disabled={isLoading}
              className="w-full px-4 py-2 bg-green-600 text-white rounded-lg hover:bg-green-700 transition-colors disabled:bg-green-300"
            >
              {isLoading ? 'Generating Speech...' : 'Generate Speech'}
            </button>
          </div>
        )}
      </div>
    </div>
  );
};

export default DocumentUploadPage;
